<?php
declare(strict_types=1);
namespace RetroWEB\Infrastructure\Persistence;

final class AggregateStatistics
{
    private \SQLite3 $db;
    public function __construct(string $path){$dir=dirname($path);if(!is_dir($dir))mkdir($dir,0700,true);$lock=fopen($path.'.init.lock','c');if($lock===false||!flock($lock,LOCK_EX))throw new \RuntimeException('Unable to initialise statistics database');try{$this->db=new \SQLite3($path);$this->db->enableExceptions(true);$this->db->busyTimeout(5000);$this->db->exec('PRAGMA journal_mode=WAL');$this->db->exec('PRAGMA synchronous=NORMAL');$this->db->exec('CREATE TABLE IF NOT EXISTS aggregates(day TEXT NOT NULL, metric TEXT NOT NULL, bucket TEXT NOT NULL, count INTEGER NOT NULL, PRIMARY KEY(day,metric,bucket))');$this->db->exec('CREATE TABLE IF NOT EXISTS daily_visitors(day TEXT NOT NULL, identity_hash TEXT NOT NULL, PRIMARY KEY(day,identity_hash))');}finally{flock($lock,LOCK_UN);fclose($lock);}}
    public function increment(string $metric,string $bucket='all',?int $now=null):void{$this->add($metric,$bucket,1,$now);}
    public function add(string$metric,string$bucket,int$amount,?int$now=null):void{if(!preg_match('/^[a-z_]{1,40}$/',$metric)||!preg_match('/^[a-zA-Z0-9_.-]{1,80}$/',$bucket)||$amount<0)throw new \InvalidArgumentException('Invalid aggregate');$day=gmdate('Y-m-d',$now??time());$stmt=$this->db->prepare('INSERT INTO aggregates(day,metric,bucket,count) VALUES(:day,:metric,:bucket,:amount) ON CONFLICT(day,metric,bucket) DO UPDATE SET count=count+excluded.count');$stmt->bindValue(':day',$day,SQLITE3_TEXT);$stmt->bindValue(':metric',$metric,SQLITE3_TEXT);$stmt->bindValue(':bucket',$bucket,SQLITE3_TEXT);$stmt->bindValue(':amount',$amount,SQLITE3_INTEGER);$stmt->execute();}
    public function recordVisit(string$identityHash,?int$now=null):bool{if(!preg_match('/^[a-f0-9]{64}$/',$identityHash))throw new \InvalidArgumentException('Invalid visitor identity');$timestamp=$now??time();$stmt=$this->db->prepare('INSERT OR IGNORE INTO daily_visitors(day,identity_hash) VALUES(:day,:identity)');$stmt->bindValue(':day',gmdate('Y-m-d',$timestamp),SQLITE3_TEXT);$stmt->bindValue(':identity',$identityHash,SQLITE3_TEXT);$stmt->execute();if($this->db->changes()!==1)return false;$this->increment('visits','new',$timestamp);return true;}
    public function pruneVisitors(?int$now=null,int$days=8):int{$cutoff=gmdate('Y-m-d',($now??time())-max(1,$days)*86400);$stmt=$this->db->prepare('DELETE FROM daily_visitors WHERE day<:cutoff');$stmt->bindValue(':cutoff',$cutoff,SQLITE3_TEXT);$stmt->execute();return$this->db->changes();}
    public function totals():array{$result=$this->db->query('SELECT metric,bucket,SUM(count) AS count FROM aggregates GROUP BY metric,bucket ORDER BY metric,bucket');$rows=[];while($row=$result->fetchArray(SQLITE3_ASSOC))$rows[]=$row;$path=dirname($this->db->querySingle('PRAGMA database_list',true)['file']).'/direct-traffic-v2.sqlite';if(is_file($path)){$traffic=new \SQLite3($path,SQLITE3_OPEN_READONLY);if($traffic->querySingle("SELECT COUNT(*) FROM sqlite_master WHERE name='permanent_ip_clients'"))$rows[]=['metric'=>'permanent_ip_blocks','bucket'=>'active','count'=>(int)$traffic->querySingle('SELECT COUNT(*) FROM permanent_ip_clients')];$traffic->close();}$submissionPath=dirname($path).'/device-submissions-v2.sqlite';if(is_file($submissionPath)){$submissions=new \SQLite3($submissionPath,SQLITE3_OPEN_READONLY);$counts=$submissions->query('SELECT status,COUNT(*) AS count FROM submissions GROUP BY status');while($row=$counts->fetchArray(SQLITE3_ASSOC))$rows[]=['metric'=>'device_submissions','bucket'=>$row['status'],'count'=>(int)$row['count']];$submissions->close();}return$rows;}
}
